import { Component, h, Prop, Element, Event, EventEmitter, State, Method, Host, Watch } from '@stencil/core';
import { Slot, Slots } from '@src/framework/decorators';
import { t } from '@src/shared/i18n';
import { InputSize, InputStatus } from './types';
import { throttle } from 'lodash-es';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import { Vue2ValueFix } from '@src/framework/decorators/vue2ValueFix';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { inputMessages } from '@fe-infra/keystone-locales';
import { Uncontrollable } from '@src/framework/decorators/uncontrollable';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { KsIconFilledClose } from '@fe-infra/keystone-icons-stencil';

const prefix = 'input';

/**
 * @slot prefix - Slot for content to be displayed before the input field.
 * @slot suffix - Slot for content to be displayed after the input field.
 * @part base - The base container of the component.
 * @part inner - The inner content container that wraps the prefix, input, character count, and suffix.
 * @part prefix - The prefix container.
 * @part input - The native input element.
 * @part suffix - The suffix container.
 */
@Component({
  tag: 'ks-input',
  styleUrl: 'index.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class KsInput extends FormBaseComponent<string> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  protected static controlledModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsInputElement;
  private inputEl!: HTMLInputElement;

  /** Sets the text direction of the native input element. */
  @Prop() dir: HTMLInputElement['dir'] = '';
  /** Whether the input field should be automatically focused when the page loads. */
  @Prop() autoFocus?: boolean;
  /** Whether the input field is read-only. When `true`, the input field cannot be edited by the user. */
  @Prop() readOnly?: boolean;
  /** The autocomplete attribute of the input field, which controls whether the browser should offer autocomplete options. */
  @Prop() autoComplete?: HTMLInputElement['autocomplete'];
  /** The current value of the input field. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: string;
  /** The default value of the input field when it is first rendered. */
  @Prop() defaultValue?: string;
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: string;
  /** The size of the input field. Possible values include `"sm"` and `"md"`. */
  @Prop() size: InputSize = 'md';
  /** The type of the input field, corresponding to the HTML input type attribute. */
  @Prop() type: HTMLInputElement['type'] = 'text';
  /** Placeholder text displayed in the input field when it is empty. */
  @Prop() placeholder?: string;
  /** Indicates whether the input field is disabled. When `true`, the input field is disabled and cannot be interacted with. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** Indicates whether the input field can be cleared by the user. When `true`, a clear button is displayed to clear the input value. */
  @Prop() clearable = false;
  /** The status of the input field. Possible values include `"default"`, `"warning"` and `"error"`. */
  @Prop() @FormContextValueReconcile() status?: InputStatus;
  /** Indicates whether to show the character count of the input field. This can be a boolean value or a function returning a number. */
  @Prop() showCount?: boolean | ((value: string) => number);
  /** The maximum length of the input value. If exceeded, the character count will be highlighted in red. */
  @Prop() maxLength?: number;
  /** Callback to get the reference of the underlying input element. */
  @Prop() inputRef?: (el?: HTMLInputElement) => void;

  /** Custom event triggered when the value of the input field changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string>;
  /** Custom event triggered when the input field is clicked. */
  @Event({ bubbles: false, composed: false }) ksClick!: EventEmitter<MouseEvent>;
  /** Custom event triggered when the clear button is clicked to clear the input field. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;
  /** Custom event triggered when the input field gains focus. */
  @Event({ bubbles: false, composed: false }) ksFocus!: EventEmitter<FocusEvent>;
  /** Custom event triggered when the input field loses focus. */
  @Event({ bubbles: false, composed: false }) ksBlur!: EventEmitter<FocusEvent>;
  /** Custom event triggered when the user presses the Enter key while the input field is focused. */
  @Event({ bubbles: false, composed: false }) ksKeydownEnter!: EventEmitter<KeyboardEvent>;

  /** The component that display in the suffix area */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;
  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;
  /**
   * @private
   * 控制器位置（eg: InputNumber +/-） 预留位置（首）
   */
  @Slot({ slotname: '_internal-controls-start' }) private controlStartSlot?: Slots;
  /**
   * @private
   * 控制器位置（eg: InputNumber +/-） 预留位置（尾）
   */
  @Slot({ slotname: '_internal-controls-end' }) private controlEndSlot?: Slots;

  @State() isFocus = false;

  private composition = false;

  @State() selection: [number | null, number | null] = [null, null];

  /** Focuses the input element. */
  // eslint-disable-next-line @typescript-eslint/require-await
  @Method()
  async focusInput() {
    this.inputEl.focus();
    this.isFocus = true;
  }
  /** Blurs the input element. */
  // eslint-disable-next-line @typescript-eslint/require-await
  @Method()
  async blurInput() {
    this.inputEl.blur();
    this.isFocus = false;
  }

  /** Sets the selection range of the input element. */
  // eslint-disable-next-line @typescript-eslint/require-await
  @Method()
  async setSelectionRange(start: number, end: number) {
    this.selection = [start, end];
  }

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  get showClear() {
    const hasValue = !!this.internalValueState;
    return this.clearable && this.isFocus && hasValue;
  }

  private handleInput = (e: Event) => {
    if (this.disabled || this.composition) {
      return;
    }
    const { value } = e.target as HTMLInputElement;
    this.selection = [this.inputEl.selectionStart, this.inputEl.selectionEnd];

    this.internalValueState = value;

    throttle(() => sendActionTracking(this.el, { eventType: 'change', componentParams: { value } }), 500);
  };

  private handleFocus = (e: FocusEvent) => {
    this.isFocus = true;
    this.ksFocus.emit(e);
    sendActionTracking(this.el, { eventType: 'focus' });
  };

  private handleBlur = (e: FocusEvent) => {
    this.isFocus = false;
    this.selection = [null, null];
    this.ksBlur.emit(e);
    sendActionTracking(this.el, { eventType: 'blur' });
  };

  private handleClear = () => {
    this.ksClear.emit();
    this.internalValueState = '';
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: '' } });
  };

  get count() {
    return typeof this.showCount === 'function'
      ? this.showCount(this.internalValueState || '')
      : this.internalValueState
        ? [...this.internalValueState].length
        : 0;
  }

  private setInputRef = (el?: HTMLInputElement) => {
    this.inputEl = el!;
    this.inputRef?.(el);
  };

  // _needSync = false;
  @Watch('selection')
  handleSelectionChange() {
    if (this.selection.every((item) => item !== null)) {
      this.inputEl?.setSelectionRange(this.selection[0], this.selection[1]);
    }
  }
  private syncValue() {
    if (this.inputEl && this.inputEl.value !== this.internalValueState && !this.composition) {
      this.inputEl.value = this.internalValueState || '';
    }
  }

  @Watch('internalValueState')
  handleInternalValueStateChange() {
    this.syncValue();
  }

  componentDidRender(): void {
    this.handleInternalValueStateChange();
    this.handleSelectionChange();
  }

  // eslint-disable-next-line max-lines-per-function
  render() {
    const showCount = this.showCount || (typeof this.maxLength === 'number' && this.showCount !== false);
    const status = showCount && this.maxLength && this.maxLength < this.count ? 'error' : this.status;
    return (
      <Host class="KsInput">
        <span
          class={{
            [`${prefix}__wrapper`]: true,
            [`${prefix}__wrapper--size-${this.size}`]: true,
            [`${prefix}__wrapper--disabled`]: !!this.disabled,
            [`${prefix}__wrapper--focus`]: this.isFocus,
            [`${prefix}__wrapper--${status}`]: !!status,
            [`${prefix}__wrapper--${status}--focus`]: !!(status && this.isFocus),
          }}
          part="base"
        >
          <div part="_internal-inner" class={`${prefix}__inner`} data-testid="ks-input-index-v6WrwD">
            {this.controlStartSlot && [
              <span class={`${prefix}__addon`} data-testid="ks-input-index-op3WnV">
                <slot name="_internal-controls-start"></slot>
              </span>,
              <div class={`${prefix}__divider`}></div>,
            ]}

            <div class={`${prefix}__content`} part="inner">
              {this.prefixSlot && (
                <span
                  class={{
                    [`${prefix}__prefix`]: true,
                    [`${prefix}__addon`]: true,
                  }}
                  part="prefix"
                >
                  <ks-text variant="bodySm">
                    <slot name="prefix"></slot>
                  </ks-text>
                </span>
              )}

              <input
                part="input"
                dir={this.dir}
                class={prefix}
                type={this.type}
                ref={this.setInputRef}
                disabled={this.disabled}
                autoFocus={this.autoFocus}
                readOnly={this.readOnly}
                autoComplete={this.autoComplete}
                placeholder={this.placeholder ?? t(inputMessages.placeholder)}
                onFocus={this.handleFocus}
                onBlur={this.handleBlur}
                onInput={this.handleInput}
                onCompositionstart={() => {
                  this.composition = true;
                }}
                onCompositionend={(event) => {
                  this.composition = false;
                  this.handleInput(event);
                }}
                onClick={(e) => {
                  if (!this.disabled) {
                    this.ksClick?.emit(e);
                  }
                }}
                onSelect={() => {
                  this.selection = [this.inputEl.selectionStart, this.inputEl.selectionEnd];
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    this.ksKeydownEnter?.emit(e);
                  }
                }}
                data-testid="ks-input-index-gYhNPj"
              />

              {this.showClear && (
                <div class={`${prefix}__clear ${prefix}__clear__disabled`}>
                  <KsIconFilledClose
                    onClick={() => {
                      if (this.disabled) return;
                      this.handleClear();
                    }}
                    size="16"
                    data-testid="ks-input-index-wc26aV"
                  />
                </div>
              )}

              {showCount && (
                <div class={`${prefix}__count`}>
                  <div
                    class={{
                      [`${prefix}__count--default`]: true,
                      [`${prefix}__count--default--error`]:
                        typeof this.maxLength === 'number' && this.maxLength < this.count,
                    }}
                  >
                    {this.count + (typeof this.maxLength === 'number' ? `/${this.maxLength}` : '')}
                  </div>
                </div>
              )}

              {this.suffixSlot && (
                <span
                  class={{
                    [`${prefix}__suffix`]: true,
                    [`${prefix}__addon`]: true,
                  }}
                  part="suffix"
                >
                  <ks-text variant="bodySm">
                    <slot name="suffix"></slot>
                  </ks-text>
                </span>
              )}
            </div>
            {this.controlEndSlot && [
              <span class={`${prefix}__addon`} data-testid="ks-input-index-9cLsnh">
                <slot name="_internal-controls-end"></slot>
              </span>,
            ]}
          </div>
        </span>
      </Host>
    );
  }
}
